import {createEnemyTables} from './enemy-tables-editor.mjs';
import {uid} from './core.mjs';
import {OBJECTIVE_TYPES,objectiveTargets} from './mission.mjs';
import {placementLabel} from './hierarchy.mjs';
import {defaults,resourcePlan} from './features.mjs';
export function createManagement({getProject,commit,modal,esc,field,selectField,renderAll,ui}){
 const enemyTables=createEnemyTables({getProject,commit,modal,field,esc});
 const names={resources:'자원·장치 배치',variables:'변수',enemies:'적',goals:'목표'},keys={resources:'resourceRules',variables:'variables',enemies:'enemyGroups',goals:'objectives'};
 const groupOptions=p=>p.objectiveGroups.map(g=>[g.id,(g.kind==='main'?'메인':'서브')+' · '+g.name]);
 const targets=p=>[...p.placements.map(q=>['tile:'+q.id,'타일 · '+placementLabel(p,q)+' · '+(q.y>=0?(q.y+1)+'층':'지하 '+Math.abs(q.y)+'층')]),...p.rooms.map(r=>['room:'+r.id,'구역 · '+r.code+' '+r.name])];
 const typeOptions=[['visit','구역 방문'],['interact','오브젝트 상호작용'],['collect','아이템 회수'],['pickup','화물 들기'],['deliver','화물 회수'],['scan','스캔 완료'],['survive','제한 시간 생존'],['clear','길 정리'],['manual','이벤트로 완료']];
 const closedGroups=new Set();
 const groupKey=(p,id)=>p.id+':'+id;
 const mainGroup=p=>p.objectiveGroups.find(g=>g.kind==='main')?.id;
 const objectiveGroup=(p,o)=>o.groupId||mainGroup(p);
 function goalTree(p){return `<div class="goal-tree" aria-label="목표 묶음">${p.objectiveGroups.map(g=>{
  const items=p.objectives.filter(o=>objectiveGroup(p,o)===g.id),inactive=p.missionMode==='extract'&&g.kind==='main';
  return `<details class="goal-group ${inactive?'inactive':''}" data-goal-group="${esc(g.id)}" ${closedGroups.has(groupKey(p,g.id))?'':'open'}><summary><span class="goal-disclosure" aria-hidden="true">▸</span><span class="goal-group-title"><strong>${g.kind==='main'?'메인 목표':esc(g.name)}</strong>${g.kind==='sub'?'<span class="goal-kind">서브</span>':''}<span class="goal-count">${items.length}개</span>${inactive?'<span class="goal-kind">미사용</span>':''}</span><span class="goal-group-actions"><button type="button" class="button" data-manage="new" data-group-id="${esc(g.id)}" aria-label="${esc(g.kind==='main'?'메인 목표':g.name)}에 목표 추가">＋ 목표</button>${g.kind==='sub'?`<button type="button" class="subtle-button" data-manage="group-edit" data-id="${esc(g.id)}" aria-label="${esc(g.name)} 이름 변경">이름 변경</button><button type="button" class="subtle-button" data-manage="group-delete" data-id="${esc(g.id)}" aria-label="${esc(g.name)} 묶음 삭제">삭제</button>`:''}</span></summary><div class="goal-children">${items.map(o=>`<article class="goal-leaf" data-goal-id="${esc(o.id)}"><div><strong>${esc(o.name)}</strong><small>${esc(OBJECTIVE_TYPES[o.type]||o.type)} · ${o.enabled===false?'비활성':'활성'}</small></div><button type="button" class="button" data-manage="edit" data-id="${esc(o.id)}" aria-label="${esc(o.name)} 편집">편집</button><button type="button" class="subtle-button" data-manage="delete" data-id="${esc(o.id)}" aria-label="${esc(o.name)} 삭제">삭제</button></article>`).join('')||'<div class="goal-empty">목표 없음</div>'}</div></details>`;
 }).join('')}</div>`;}
 document.addEventListener('toggle',e=>{const el=e.target;if(!el.matches?.('[data-goal-group]'))return;const key=groupKey(getProject(),el.dataset.goalGroup);if(el.open)closedGroups.delete(key);else closedGroups.add(key);},true);
 function render(section){if(section==='enemies')return enemyTables.render();const p=defaults(getProject());let capacity='';if(section==='resources'){try{const plan=resourcePlan(p);capacity='배치 가능한 묶음 '+plan.allocations.length+'개 · 실제 위치는 임무 준비 시 추첨';}catch(error){capacity=error.message;}}const items=p[keys[section]]||[];return `<div class="management-heading"><h2>${names[section]}</h2>${section==='goals'?'<button class="button primary" data-manage="group">＋ 서브 목표 묶음</button>':'<button class="button primary" data-manage="new">＋ 추가</button>'}</div>${section==='resources'?`<p class="resource-capacity" role="status">${esc(capacity)}</p>`:''}${section==='goals'?`<div class="management-settings"><label>임무 방식<select aria-label="임무 방식" data-mission-mode><option value="extract" ${p.missionMode==='extract'?'selected':''}>탈출 자체가 목표</option><option value="objectives" ${p.missionMode!=='extract'?'selected':''}>메인 목표 달성 후 탈출</option></select></label><label ${p.missionMode==='extract'?'hidden':''}>메인 목표 완료 결과<select aria-label="메인 목표 완료 결과" data-success-mode><option value="extraction" ${p.successMode==='extraction'?'selected':''}>탈출구 활성화</option><option value="direct" ${p.successMode==='direct'?'selected':''}>즉시 탈출 · 임무 성공</option></select></label></div>`:''}${section==='goals'?`<div class="extraction-locations"><h3>탈출 위치</h3>${p.gimmicks.filter(g=>g.type==='extraction').map(g=>`<button class="button" data-select-kind="gimmick" data-select-id="${esc(g.id)}">${esc(g.name)} · 위치·스캔 설정</button>`).join('')||'<button class="button" data-section="tiles">타일을 선택해 탈출 타일로 지정</button>'}</div>`:''}${section==='goals'?goalTree(p):`<div class="management-items">${items.map(x=>`<article><div><strong>${esc(x.name)}</strong><small>${section==='variables'?'초기값 '+x.initial:section==='resources'?`${x.kind} · 총 ${x.total}회 · ${x.bundles}묶음`:section==='enemies'?`${x.entity} · ${x.count}마리 · ${x.waves===0?'무한':x.waves+'회'} · ${x.interval}초`:p.objectiveGroups.find(g=>g.id===(x.groupId||'main'))?.name||'메인'}</small></div><button class="button" data-manage="edit" data-id="${esc(x.id)}">편집</button><button class="subtle-button" data-manage="delete" data-id="${esc(x.id)}">삭제</button></article>`).join('')||'<p class="empty-state">아직 등록된 항목이 없습니다.</p>'}</div>`}${section==='resources'?`<div class="divider"></div><div class="management-heading"><h3>고정 요소 · 스캔 및 장치</h3><button class="button" data-action="new-device">＋ 배치</button></div><div class="management-items">${p.gimmicks.filter(g=>!['spawn','extraction'].includes(g.type)).map(g=>`<article><strong>${esc(g.name)}</strong><button class="button" data-select-kind="gimmick" data-select-id="${esc(g.id)}">위치·설정</button></article>`).join('')}</div><p class="note subtle">총량은 사용 횟수입니다. 한 팩 최대 5회분, 한 수납 칸에 한 팩씩 배정합니다. NBT 컨테이너와 액자가 배치 후보입니다.</p>`:''}`;}
 function edit(section,id,defaultGroupId){const p=defaults(getProject()),old=p[keys[section]].find(x=>x.id===id)||{},name=old.name||'새 '+names[section],scope=(old.scope||'tile')+':'+(old.targetId||p.placements[0]?.id||'');let body=field('이름','name',name,'text','required maxlength="160"');
 if(section==='variables')body+=field('초기값','initial',old.initial??0,'number','required min="-1000000000" max="1000000000"');
 if(section==='resources')body+=selectField('종류','kind',old.kind||'ammo',[['ammo','탄약 보급'],['health','체력 보급'],['cargo','운반 화물'],['keycard','ID 키카드'],['object','상호작용 오브젝트']])+selectField('배치 범위','scope',scope,targets(p))+field('총 사용량 · 오브젝트는 개수','total',old.total??1,'number','min="1" max="5000" required')+field('나눌 묶음 수','bundles',old.bundles??1,'number','min="1" max="1000" required')+field('대상 식별자','objectKey',old.objectKey||'','text','maxlength="160"');
 if(section==='enemies')body+=field('몹 엔티티 ID','entity',old.entity||'minecraft:zombie','text','required maxlength="160"')+selectField('생성 범위','scope',scope,targets(p))+field('한 번에 생성할 수','count',old.count??6,'number','min="1" max="64" required')+field('생성 횟수 · 0은 무한','waves',old.waves??1,'number','min="0" max="1000" required')+field('간격 · 초','interval',old.interval??15,'number','min="1" max="3600" required')+field('플레이어로부터 최소 거리 · 블록','minDistance',old.minDistance??4,'number','min="0" max="128" required')+`<label><input type="checkbox" name="sleeping" ${old.sleeping?'checked':''}> 동면 상태 · 경보로 깨우기</label><label><input type="checkbox" name="enabled" ${old.enabled?'checked':''}> 스테이지 시작부터 생성</label>`;
 if(section==='goals')body+=selectField('묶음','groupId',old.groupId||defaultGroupId||mainGroup(p),groupOptions(p))+selectField('종류','type',old.type||'visit',old.type==='command'?[...typeOptions,['command','터미널 명령어 · 지원 종료']]:typeOptions)+'<div id="goalFields"></div>'+`<label><input type="checkbox" name="enabled" ${old.enabled!==false?'checked':''}> 처음부터 활성화</label>`;

 modal(names[section]+' 편집',body,data=>{const raw=Object.fromEntries(data),scopeValue=raw.scope?.split(':');return commit(d=>{defaults(d);const x={...old,id:old.id||uid(section),name:raw.name.trim()};if(section==='variables')x.initial=Number(raw.initial);if(section==='resources')Object.assign(x,{kind:raw.kind,scope:scopeValue[0],targetId:scopeValue.slice(1).join(':'),total:Number(raw.total),bundles:Number(raw.bundles),objectKey:raw.objectKey});if(section==='enemies')Object.assign(x,{entity:raw.entity,scope:scopeValue[0],targetId:scopeValue.slice(1).join(':'),count:Number(raw.count),waves:Number(raw.waves),interval:Number(raw.interval),minDistance:Number(raw.minDistance),sleeping:data.has('sleeping'),enabled:data.has('enabled')});if(section==='goals')Object.assign(x,{groupId:raw.groupId,type:raw.type,targetId:raw.targetId||'',amount:Number(raw.amount||1),enabled:data.has('enabled'),required:d.objectiveGroups.find(g=>g.id===raw.groupId)?.kind==='main',command:raw.command||''});const list=d[keys[section]],i=list.findIndex(q=>q.id===x.id);if(i<0)list.push(x);else list[i]=x;});});
 if(section==='goals'){
  const type=document.querySelector('#dialogBody [name=type]');const host=document.getElementById('goalFields');
  const values=new Map();let previous=null;
  const update=()=>{if(previous)values.set(previous,Object.fromEntries([...host.querySelectorAll('input,select')].map(e=>[e.name,e.value])));const kind=type.value,v=values.get(kind)||(kind===old.type?old:{});previous=kind;
   const options=objectiveTargets(p,kind);let target=v.targetId||options[0]?.[0]||'';
   if(target&&!options.some(([id])=>id===target))options.unshift([target,'연결되지 않은 대상 · '+target]);
   host.innerHTML=(!['manual','survive'].includes(kind)?selectField('대상','targetId',target,options.length?options:[['','배치된 대상 없음']]):'')+(kind==='command'?field('터미널 명령어 · 지원 종료','command',v.command||''):'')+(['collect','pickup','deliver','survive'].includes(kind)?field(kind==='survive'?'생존 시간 · 초':'필요 수량','amount',v.amount??1,'number','min="1" max="3600" required'):'');
  };type.addEventListener('change',update);update();
 }

 }
 function click(e){const b=e.target.closest('[data-manage]');if(!b)return;const section=ui.section;if(!keys[section])return;const id=b.dataset.id,a=b.dataset.manage;
 if(a==='new'||a==='edit'){e.preventDefault();if(b.dataset.groupId)closedGroups.delete(groupKey(getProject(),b.dataset.groupId));return edit(section,id,b.dataset.groupId);}if(a==='delete')return commit(p=>{p[keys[section]]=p[keys[section]].filter(x=>x.id!==id);});
 if(a==='group-delete')return commit(p=>{if(p.objectives.some(o=>objectiveGroup(p,o)===id))throw Error('묶음의 목표를 먼저 옮기거나 삭제하세요.');p.objectiveGroups=p.objectiveGroups.filter(g=>g.id!==id);});
 if(a==='group'||a==='group-edit'){const group=getProject().objectiveGroups.find(g=>g.id===id);modal('서브 목표 묶음',field('이름','name',group?.name||'새 서브 목표','text','required maxlength="160"'),data=>commit(p=>{if(group)p.objectiveGroups.find(g=>g.id===id).name=data.get('name').trim();else p.objectiveGroups.push({id:uid('group'),name:data.get('name').trim(),kind:'sub'});}));}
 }
 document.addEventListener('click',click);document.addEventListener('change',e=>{if(e.target.matches('[data-mission-mode]'))commit(p=>{p.missionMode=e.target.value;if(p.missionMode==='extract')p.successMode='extraction';});if(e.target.matches('[data-success-mode]'))commit(p=>p.successMode=e.target.value);});
 return {render,edit,editTable:enemyTables.edit};
}
